function LANG(){ try{ return localStorage.getItem('nexumo_lang') || 'es'; }catch(e){ return 'es'; } }
function T(k){ const l = LANG(); return (I18N[l] && I18N[l][k] != null) ? I18N[l][k] : (I18N.es[k] != null ? I18N.es[k] : k); }
function setLang(l){ try{ localStorage.setItem('nexumo_lang', l); }catch(e){} location.reload(); }
function toggleLang(e){ if(e) e.stopPropagation(); const m = document.getElementById('langMenu'); if(m) m.classList.toggle('open'); }
document.addEventListener('click', () => { const m = document.getElementById('langMenu'); if(m) m.classList.remove('open'); });

function prodLoc(p){
  const l = LANG();
  if(l === 'es' || !I18N.P[l] || !I18N.P[l][p.id]) return p;
  const t = I18N.P[l][p.id];
  const c = Object.assign({}, p);
  if(t.name) c.name = t.name;
  if(t.t1) c.title1 = t.t1;
  if(t.t2) c.title2 = t.t2;
  if(p.badge === 'OFERTA') c.badge = T('prod.deal');
  let m = String(p.stock || '').match(/(\d+)\s*in stock/i);
  if(m) c.stock = m[1] + ' ' + T('prod.instock');
  else if(/in stock/i.test(p.stock || '')) c.stock = T('prod.instock');
  return c;
}

